<template><view class="number-editor"><text class="number-label">学号</text><text v-if="loading" class="number-state">正在读取</text><template v-else-if="ready"><input v-if="editable" v-model="draft" class="number-input" maxlength="64" :disabled="saving||uncertain" placeholder="填写当前入学机构的学号"/><text v-else class="number-value">{{draft||'未设置'}}</text><button v-if="editable" class="number-save" :disabled="saving||uncertain" :loading="saving" @tap="save">保存学号</button></template><text v-if="error" class="number-error">{{error}}</text><button v-if="error" class="number-reload" :disabled="saving" @tap="load">重新读取</button></view></template>
<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';import {academicMetadataApi} from '@/api/academic-metadata';import {studentNumberDraft} from '@/models/academic-metadata-draft';import {getOrganizationSession} from '@/session/organization-session';
const props=defineProps<{token:string;scope:string;studentId:string;editable:boolean}>();const emit=defineEmits<{(e:'saved',studentNumber:string|null):void}>();
const draft=ref(''),error=ref(''),loading=ref(false),saving=ref(false),uncertain=ref(false),ready=ref(false);let revision=0,alive=true,versionNo=0;
function scopeValid(){const selected=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string}|undefined;return alive&&!!props.token&&getOrganizationSession()?.accessToken===props.token&&selected?.accessToken===props.token&&selected?.organizationId===props.scope;}
function current(n:number){return n===revision&&scopeValid();}
async function load(){if(saving.value)return;const n=++revision;ready.value=false;loading.value=true;error.value='';try{if(!scopeValid())throw Error('组织或账号已变化，请重新进入');const value=await academicMetadataApi.readNumber(props.token,props.scope,props.studentId);if(!current(n))return;if(value.studentId!==props.studentId||value.institutionId!==props.scope||!Number.isInteger(value.versionNo)||value.versionNo<0)throw Error('学号响应范围或版本不一致');versionNo=value.versionNo;draft.value=value.studentNumber||'';ready.value=true;uncertain.value=false;}catch(e){if(current(n))error.value=e instanceof Error?e.message:'学号读取失败';}finally{if(n===revision)loading.value=false;}}
async function save(){if(!ready.value||loading.value||saving.value||uncertain.value||!props.editable||!scopeValid())return;const n=revision;let attempted=false;error.value='';try{const value=studentNumberDraft(draft.value,versionNo);saving.value=true;attempted=true;const result=await academicMetadataApi.updateNumber(props.token,props.scope,props.studentId,value.studentNumber,value.versionNo);if(!current(n))return;if(result.studentId!==props.studentId||result.institutionId!==props.scope||result.versionNo!==versionNo+1)throw Error('保存结果待核对，请重新读取');versionNo=result.versionNo;draft.value=result.studentNumber||'';emit('saved',result.studentNumber);}catch(e){if(current(n)){uncertain.value=attempted;error.value=e instanceof Error?e.message:'保存结果待确认，请重新读取';}}finally{if(n===revision)saving.value=false;}}
watch(()=>[props.token,props.scope,props.studentId],()=>{++revision;saving.value=false;loading.value=false;ready.value=false;draft.value='';uncertain.value=false;void load();},{immediate:true});onBeforeUnmount(()=>{alive=false;++revision;draft.value='';});
</script>
<style scoped>.number-editor{margin-top:24rpx;padding-top:22rpx;border-top:1rpx solid #e3ebe6}.number-label{display:block;font-size:27rpx;color:#5c7868;margin-bottom:14rpx}.number-input{height:72rpx;padding:0 20rpx;background:#f5f9f6;border:1rpx solid #dce7df;border-radius:16rpx;font-size:28rpx}.number-save,.number-reload{margin:18rpx 0 0;font-size:26rpx;line-height:70rpx;border-radius:16rpx;background:#155e45;color:#fff}.number-reload{background:#eef5ef;color:#315f48}.number-error{display:block;color:#b35145;font-size:25rpx;margin-top:14rpx}.number-state,.number-value{font-size:27rpx;color:#6b8173}button::after{border:0}</style>
